use crate::config_toml::ReconnectConfigToml;
use std::sync::RwLock;

static OVERRIDE: RwLock<Option<ReconnectConfigToml>> = RwLock::new(None);

/// Resolve the process override, falling back to the session's startup configuration.
pub fn effective_reconnect_config(defaults: ReconnectConfigToml) -> ReconnectConfigToml {
    OVERRIDE
        .read()
        .unwrap_or_else(std::sync::PoisonError::into_inner)
        .unwrap_or(defaults)
}

/// Replace the process override. Passing no override restores configuration defaults.
pub fn set_reconnect_override(config: Option<ReconnectConfigToml>) {
    *OVERRIDE
        .write()
        .unwrap_or_else(std::sync::PoisonError::into_inner) = config;
}

