#[tokio::test]
async fn reconnect_override_changes_existing_session_and_restores_startup_defaults() -> Result<()> {
    let _reset = ResetOverride;
    let server = responses::start_mock_server().await;
    let response_mock =
        responses::mount_response_sequence(&server, vec![ResponseTemplate::new(504); 8]).await;
    let defaults = ReconnectConfigToml {
        mode: ReconnectMode::Fixed,
        interval_ms: Some(25),
        max_retries: Some(1),
    };
    let test = test_codex()
        .with_config(move |config| {
            config.service_tier = Some("flex".into());
            config.model_provider.request_max_retries = Some(0);
            config.model_provider.stream_max_retries = Some(0);
            config.reconnect = defaults;
        })
        .build_with_auto_env(&server)
        .await?;
    let config_path = test.config.codex_home.join("config.toml");
    let original_file = std::fs::read(&config_path).ok();
    for (runtime, request_count) in [
        (None, 2),
        (
            Some(ReconnectConfigToml {
                max_retries: Some(0),
                ..defaults
            }),
            3,
        ),
        (
            Some(ReconnectConfigToml {
                max_retries: Some(2),
                ..defaults
            }),
            6,
        ),
        (None, 8),
    ] {
        set_reconnect_override(runtime);
        test.submit_text_turn("exercise the current retry budget")
            .await?;
        assert_eq!(response_mock.requests().len(), request_count);
        assert_eq!(std::fs::read(&config_path).ok(), original_file);
    }
    set_reconnect_override(/*config*/ None);
    assert_eq!(codex_config::effective_reconnect_config(defaults), defaults);
    Ok(())
}

#[tokio::test]
async fn reconnect_override_bounds_connection_failures_during_an_active_turn() -> Result<()> {
    let _reset = ResetOverride;
    let server = responses::start_mock_server().await;
    let unavailable_socket = TcpSocket::new_v4()?;
    unavailable_socket.bind("127.0.0.1:0".parse()?)?;
    let unavailable_address = unavailable_socket.local_addr()?;
    let defaults = ReconnectConfigToml {
        mode: ReconnectMode::Fixed,
        interval_ms: Some(25),
        max_retries: Some(1),
    };
    let test = test_codex()
        .with_config(move |config| {
            config.model_provider.base_url = Some(format!("http://{unavailable_address}/v1"));
            config.model_provider.request_max_retries = Some(0);
            config.model_provider.supports_websockets = false;
            config.reconnect = defaults;
        })
        .build_with_auto_env(&server)
        .await?;
    test.codex
        .start_or_steer_turn(TurnInputRequest::user_input(vec![UserInput::Text {
            text: "stop when the updated retry budget is exhausted".into(),
            text_elements: Vec::new(),
        }]))
        .await?;
    let mut retries = 0;
    loop {
        let event = wait_for_event(&test.codex, |event| {
            matches!(event, EventMsg::StreamError(_) | EventMsg::TurnComplete(_))
        })
        .await;
        match event {
            EventMsg::StreamError(_) => {
                retries += 1;
                if retries == 1 {
                    set_reconnect_override(Some(ReconnectConfigToml {
                        max_retries: Some(2),
                        ..defaults
                    }));
                }
            }
            EventMsg::TurnComplete(event) => {
                assert!(event.error.is_some());
                break;
            }
            _ => unreachable!("only retries and turn completion pass the event filter"),
        }
    }
    assert_eq!(retries, 2);
    Ok(())
}

